<?php
declare(strict_types=1);
require_once __DIR__.'/../app/bootstrap.php';
$t=(string)($_GET['token']??$_POST['token']??'');$err=null;$valid=false;
if(preg_match('/^[a-f0-9]{64}$/',$t)){$s=db()->prepare('SELECT id FROM password_resets WHERE token_hash=? AND used_at IS NULL AND expires_at>NOW()');$s->execute([hash('sha256',$t)]);$valid=(bool)$s->fetch();}
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$pw=(string)($_POST['password']??'');$cf=(string)($_POST['confirm_password']??'');if(!$valid)$err='Reset token is invalid or expired.';elseif($pw!==$cf)$err='Passwords do not match.';elseif(strlen($pw)<12||!preg_match('/[A-Za-z]/',$pw)||!preg_match('/[0-9]/',$pw))$err='Use at least 12 characters with letters and numbers.';else{db()->beginTransaction();try{$s=db()->prepare('SELECT id,user_id FROM password_resets WHERE token_hash=? AND used_at IS NULL AND expires_at>NOW() FOR UPDATE');$s->execute([hash('sha256',$t)]);$r=$s->fetch();if(!$r)throw new RuntimeException();db()->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($pw,PASSWORD_DEFAULT),$r['user_id']]);db()->prepare('UPDATE password_resets SET used_at=NOW() WHERE id=?')->execute([$r['id']]);db()->commit();audit('auth.password_reset',null);flash('success','Password updated. Sign in with your new password.');go('/login');}catch(Throwable $ex){if(db()->inTransaction())db()->rollBack();$err='Reset link could not be used. Request a new link.';}}}
$html=$err?'<div class="alert error">'.e($err).'</div>':'';if(!$valid)$html.='<p>Link invalid or expired. <a href="/forgot-password">Request a new one</a>.</p>';else $html.='<form method="post">'.csrf().'<input type="hidden" name="token" value="'.e($t).'"><label>New password<input type="password" name="password" required minlength="12"></label><label>Confirm password<input type="password" name="confirm_password" required minlength="12"></label><button class="primary">Update password</button></form>';
page('Reset password',$html);
